<?php
require_once '../includes/auth.php'; require_role('teacher'); require_once '../config/db.php';
$page_title='Course Notes'; $msg=''; $err=''; $teacherUser=$_SESSION['username']; require_once '../includes/teacher_context.php';

if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['upload_note'])){
    $assignmentId=(int)($_POST['teaching_assignment_id']??0);
    $ctx=teacher_context_valid_assignment($conn,$teacherUser,$assignmentId,$teacher_context_semester);
    $title=trim($_POST['title']??'');$file=$_FILES['notes']??null;$allowed=['pdf','doc','docx','ppt','pptx'];
    if(!$ctx)$err='Select one of your assigned subjects for the selected semester.';
    elseif($title===''||!$file||$file['error']!==UPLOAD_ERR_OK)$err='Enter a note title and choose a file.';
    else{$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!in_array($ext,$allowed,true))$err='Use PDF, Word or PowerPoint files.';else{$dir=__DIR__.'/../uploads/notes/';if(!is_dir($dir))mkdir($dir,0777,true);$name=time().'_'.bin2hex(random_bytes(4)).'_'.preg_replace('/[^A-Za-z0-9._-]/','_',basename($file['name']));if(move_uploaded_file($file['tmp_name'],$dir.$name)){$st=$conn->prepare("INSERT INTO tbl_notes(teacher_username,batch_id,semester,title,subject,file_path) VALUES(?,?,?,?,?,?)");$st->bind_param('siisss',$teacherUser,$ctx['batch_id'],$ctx['semester'],$title,$ctx['subject'],$name);if($st->execute())$msg='Notes published to '.$ctx['batch_name'].' · Semester '.$ctx['semester'].' · '.$ctx['subject'].'.';else{@unlink($dir.$name);$err='Could not save the note.';}}else$err='Unable to save the uploaded file.';}}
}
if(isset($_POST['delete_note'])){$id=(int)$_POST['note_id'];$st=$conn->prepare("SELECT file_path FROM tbl_notes WHERE id=? AND teacher_username=?");$st->bind_param('is',$id,$teacherUser);$st->execute();$n=$st->get_result()->fetch_assoc();if($n){@unlink(__DIR__.'/../uploads/notes/'.basename($n['file_path']));$d=$conn->prepare("DELETE FROM tbl_notes WHERE id=? AND teacher_username=?");$d->bind_param('is',$id,$teacherUser);$d->execute();$msg='Note removed.';}}
$st=$conn->prepare("SELECT n.*,b.batch_name,b.course FROM tbl_notes n LEFT JOIN tbl_batches b ON b.id=n.batch_id WHERE n.teacher_username=? ORDER BY n.uploaded_at DESC");$st->bind_param('s',$teacherUser);$st->execute();$notes=$st->get_result();
require '../includes/header.php';
?>
<div class="glass-hero mb-4"><div><span class="eyebrow-dark">TEACHING MATERIALS</span><h2>Course Notes</h2><p>Course and batch are fixed by the administrator. Select the subject for your current semester.</p></div><div class="hero-orb"><i class="fa-solid fa-book-open"></i></div></div>
<?php if($msg):?><div class="alert alert-success glass-alert"><?php echo e($msg);?></div><?php endif;?><?php if($err):?><div class="alert alert-danger glass-alert"><?php echo e($err);?></div><?php endif;?>
<div class="row g-4"><div class="col-lg-5"><div class="glass-card"><div class="section-kicker">SEMESTER <?php echo $teacher_context_semester;?></div><h5>Upload Notes</h5><div class="context-readonly mb-3"><span><strong>Course</strong><small><?php echo e($teacher_context_batch['course']??'Not assigned');?></small></span><span><strong>Batch</strong><small><?php echo e($teacher_context_batch['batch_name']??'Not assigned');?></small></span></div><form method="POST" enctype="multipart/form-data" class="mt-3"><input type="hidden" name="upload_note" value="1"><label class="form-label">Subject</label><select class="form-select mb-3" name="teaching_assignment_id" required><option value="">Select subject</option><?php foreach($teacher_context_options as $o): if((int)$o['batch_id']!==$teacher_context_batch_id || (int)$o['semester']!==$teacher_context_semester)continue; ?><option value="<?php echo (int)$o['id'];?>"><?php echo e($o['subject']);?></option><?php endforeach;?></select><label class="form-label">Note title</label><input class="form-control mb-3" name="title" placeholder="Unit 1 - Introduction" required><label class="form-label">File</label><input class="form-control" type="file" name="notes" accept=".pdf,.doc,.docx,.ppt,.pptx" required><button class="btn btn-primary w-100 mt-3"><i class="fa-solid fa-cloud-arrow-up"></i> Publish Notes</button></form></div></div>
<div class="col-lg-7"><div class="glass-card"><div class="d-flex justify-content-between align-items-center"><div><div class="section-kicker">LIBRARY</div><h5 class="mb-1">My Uploaded Notes</h5><span class="small-muted">Every file keeps its subject, batch and semester.</span></div><span class="badge badge-soft"><?php echo $notes->num_rows;?> files</span></div><div class="notes-grid mt-4"><?php if($notes->num_rows===0):?><div class="empty">You have not uploaded any notes yet.</div><?php endif;?><?php while($n=$notes->fetch_assoc()):?><div class="note-card glass-subcard"><div class="note-icon"><i class="fa-solid fa-file-lines"></i></div><span class="context-chip small-chip"><?php echo e(($n['batch_name']??'Unassigned').' · Sem '.($n['semester']??'-'));?></span><h6><?php echo e($n['title']);?></h6><div class="small-muted"><?php echo e($n['subject']);?> · <?php echo e(date('d M Y',strtotime($n['uploaded_at'])));?></div><div class="d-flex gap-2 mt-3"><a class="btn btn-sm btn-primary" target="_blank" href="../uploads/notes/<?php echo rawurlencode(basename($n['file_path']));?>">Open</a><form method="POST" onsubmit="return confirm('Delete this note?');"><input type="hidden" name="delete_note" value="1"><input type="hidden" name="note_id" value="<?php echo (int)$n['id'];?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></div><?php endwhile;?></div></div></div></div>
<?php require '../includes/footer.php'; ?>
